{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.shinpr/mcp-image",
  "description": "AI image generation and editing with prompt optimization and quality presets",
  "vendor": "Shinsuke Kagawa",
  "license": "MIT",
  "repository": {
    "url": "https://github.com/shinpr/mcp-image",
    "source": "github"
  },
  "version": "0.11.3",
  "packages": [
    {
      "registryType": "npm",
      "registryBaseUrl": "https://registry.npmjs.org",
      "identifier": "mcp-image",
      "version": "0.11.3",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "IMAGE_PROVIDER",
          "description": "Image provider to use: 'gemini' (default) or 'openai'",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "GEMINI_API_KEY",
          "description": "Google Gemini API key for image generation when IMAGE_PROVIDER=gemini (get from https://aistudio.google.com/apikey)",
          "isRequired": false,
          "format": "string",
          "isSecret": true
        },
        {
          "name": "OPENAI_API_KEY",
          "description": "OpenAI API key for image generation when IMAGE_PROVIDER=openai. Requires OpenAI organization verification to access gpt-image-2 (https://platform.openai.com/settings/organization/general)",
          "isRequired": false,
          "format": "string",
          "isSecret": true
        },
        {
          "name": "IMAGE_OUTPUT_DIR",
          "description": "Absolute path to directory where generated images will be saved (defaults to ./output)",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "IMAGE_QUALITY",
          "description": "Default quality preset: 'fast' (Nano Banana 2, default), 'balanced' (Nano Banana 2 + thinking), 'quality' (Nano Banana Pro)",
          "isRequired": false,
          "format": "string",
          "isSecret": false
        },
        {
          "name": "SKIP_PROMPT_ENHANCEMENT",
          "description": "Set to 'true' to disable automatic prompt optimization and use direct prompts",
          "isRequired": false,
          "format": "boolean",
          "isSecret": false
        }
      ],
      "features": {
        "tools": {
          "supported": true,
          "list": [
            "generate_image"
          ]
        },
        "prompts": {
          "supported": false
        },
        "resources": {
          "supported": true
        }
      }
    }
  ],
  "tags": [
    "mcp",
    "mcp-server",
    "image-generation",
    "generative-ai",
    "image-editing",
    "prompt-enhancement",
    "gemini",
    "openai",
    "gpt-image-2",
    "nano-banana",
    "nano-banana-2",
    "nano-banana-pro",
    "google-ai",
    "ai-tools",
    "agent-skills",
    "skills"
  ],
  "homepage": "https://github.com/shinpr/mcp-image",
  "documentation": "https://github.com/shinpr/mcp-image#readme"
}
